async function enterConfig(btn,syncUrl=false){try{await loadConfig();configUnlocked=true;activateView(btn,{syncUrl})}catch(error){if(error.status===401){openConfigAuth(btn,syncUrl)}else showError(error)}}
async function enterLicense(btn,syncUrl=false){try{await loadLicenses();licenseUnlocked=true;activateView(btn,{syncUrl})}catch(error){if(error.status===401){openConfigAuth(btn,syncUrl,'license')}else showError(error)}}
async function loadLicenses(){const [rows,status]=await Promise.all([api('/api/licenses'),api('/api/licenses/status')]);allLicenses=rows;renderLicenseAvailability(status);renderLicenses(rows)}
function navigateToView(btn,syncUrl=false){if(btn.dataset.view==='config'&&!configUnlocked){enterConfig(btn,syncUrl);return}if(btn.dataset.view==='licenses'&&!licenseUnlocked){enterLicense(btn,syncUrl);return}activateView(btn,{syncUrl});if(btn.dataset.view==='config')loadConfig().catch(error=>{if(error.status===401){configUnlocked=false;openConfigAuth(btn,syncUrl)}else showError(error)})}
$$('.nav').forEach(btn=>btn.onclick=event=>{event.preventDefault();navigateToView(btn,true)});
addEventListener('popstate',()=>{const btn=document.querySelector(`.nav[data-view="${viewForLocation()}"]`);if(btn)navigateToView(btn,false)});
const initialNav=document.querySelector(`.nav[data-view="${viewForLocation()}"]`);if(initialNav)navigateToView(initialNav,false);
async function refreshData(){const button=$('#refreshBtn');button.disabled=true;button.textContent='采集中…';$('#healthDetail').textContent='正在执行 LSF / FlexNet 实时采集';try{await api('/api/refresh',{method:'POST',timeout:60000});await load();button.textContent='采集完成'}catch(error){$('#healthText').textContent='采集失败';$('#healthDetail').textContent=error.message;console.error(error);button.textContent='采集失败'}finally{setTimeout(()=>{button.disabled=false;button.textContent='刷新数据'},1000)}}
$('#themeToggle').onclick=()=>{applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');drawHistory(historyRows)};$('#refreshBtn').onclick=()=>refreshData();$('#jobSearch').oninput=()=>renderJobs();$('#jobStatus').onchange=()=>renderJobs();$('#jobQueue').oninput=()=>renderJobs();$('#jobNode').oninput=()=>renderJobs();$('#jobSort').onchange=()=>renderJobs();$('#jobReset').onclick=()=>{$('#jobSearch').value='';$('#jobStatus').value='';$('#jobQueue').value='';$('#jobNode').value='';$('#jobSort').value='submit_time';renderJobs()};$('#userSearch').oninput=()=>renderUsers();$('#userActivityFilter').onchange=()=>renderUsers();$('#userSort').onchange=()=>renderUsers();$('#userReset').onclick=()=>{$('#userSearch').value='';$('#userActivityFilter').value='';$('#userSort').value='user';renderUsers()};$('#licenseSearch').oninput=()=>renderLicenses();$('#licenseStatus').onchange=()=>renderLicenses();$('#queueSearch').oninput=()=>renderQueues();$('#queueStatusFilter').onchange=()=>renderQueues();$('#queueLoadFilter').onchange=()=>renderQueues();$('#queueSort').onchange=()=>renderQueues();$('#queueReset').onclick=()=>{$('#queueSearch').value='';$('#queueStatusFilter').value='';$('#queueLoadFilter').value='';$('#queueSort').value='name';renderQueues()};$('#hostSearch').oninput=()=>renderHosts();$('#hostQueueFilter').onchange=()=>renderHosts();$('#hostStatusFilter').onchange=()=>renderHosts();$('#hostActivityFilter').onchange=()=>renderHosts();$('#hostSort').onchange=()=>renderHosts();$('#hostReset').onclick=()=>{$('#hostSearch').value='';$('#hostQueueFilter').value='';$('#hostStatusFilter').value='';$('#hostActivityFilter').value='';$('#hostSort').value='name';renderHosts()};function showError(e){$('#healthText').textContent='连接失败';$('#healthDetail').textContent='无法连接 CADFlow API';console.error(e)}load().catch(showError);setInterval(()=>load().catch(showError),60000);addEventListener('resize',()=>api('/api/history').then(rows=>{historyRows=rows;drawHistory(rows)}));
const resetJobPageAndRender=()=>{jobPage=1;renderJobs()};const resetUserPageAndRender=()=>{userPage=1;renderUsers()};$('#jobSearch').oninput=resetJobPageAndRender;$('#jobStatus').onchange=resetJobPageAndRender;$('#jobQueue').oninput=resetJobPageAndRender;$('#jobNode').oninput=resetJobPageAndRender;$('#jobSort').onchange=resetJobPageAndRender;$('#jobReset').onclick=()=>{$('#jobSearch').value='';$('#jobStatus').value='';$('#jobQueue').value='';$('#jobNode').value='';$('#jobSort').value='submit_time';resetJobPageAndRender()};$('#userSearch').oninput=resetUserPageAndRender;$('#userActivityFilter').onchange=resetUserPageAndRender;$('#userSort').onchange=resetUserPageAndRender;$('#userReset').onclick=()=>{$('#userSearch').value='';$('#userActivityFilter').value='';$('#userSort').value='user';resetUserPageAndRender()};
$('#addLicenseSource').onclick=()=>{licenseSources=readLicenseSources();licenseSources.push({server:'',vendor:''});renderLicenseSources()};
$('#configForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f));d.collect_interval_seconds=Number(d.collect_interval_seconds);d.command_timeout_seconds=Number(d.command_timeout_seconds);d.stale_after_seconds=Number(d.stale_after_seconds);d.db_retention_days=Number(d.db_retention_days);d.db_max_size_mb=Number(d.db_max_size_mb);d.lsf_env=envToObject(d.lsf_env);const m=$('#configMessage');m.textContent='正在预检…';const r=await fetch('/api/config',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}),body=await r.json();if(r.status===401){configUnlocked=false;openConfigAuth(document.querySelector('.nav[data-view="config"]'));return}m.textContent=r.ok?'LSF 配置保存成功，预检已通过。':`失败：${body.detail||'配置无效'}`;if(r.ok)load().catch(showError)};
$('#licenseConfigForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,payload={lmstat_path:f.elements.lmstat_path.value.trim(),license_sources:readLicenseSources()},m=$('#licenseConfigMessage');m.textContent='正在保存…';const response=await fetch('/api/license-config',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),body=await response.json();if(response.status===401){configUnlocked=false;openConfigAuth(document.querySelector('.nav[data-view="config"]'));return}m.textContent=response.ok?'FlexNet 配置保存成功，下一次采集生效。':`失败：${body.detail||'配置无效'}`;if(response.ok){licenseSources=body.license_sources||payload.license_sources;renderLicenseSources();load().catch(showError)}};
async function waitForUpdatedService(){const message=$('#configMessage');for(let attempt=0;attempt<30;attempt++){await new Promise(resolve=>setTimeout(resolve,1000));try{const response=await fetch('/api/health',{cache:'no-store',credentials:'same-origin'});if(response.ok){message.textContent='更新完成，服务已恢复。请刷新页面确认版本。';return}}catch(error){/* expected while the server restarts */}}message.textContent='更新已启动，但服务尚未恢复；请查看更新日志后再处理。'}
$('#updateBtn').onclick=async()=>{if(!window.confirm('将从当前 Git 上游快进拉取最新代码并重启 CADFlow。生产服务会短暂中断，确认继续吗？'))return;const button=$('#updateBtn'),message=$('#configMessage');button.disabled=true;button.textContent='更新中…';message.textContent='已启动更新，服务即将重启…';try{const response=await fetch('/api/update',{method:'POST',credentials:'same-origin'}),body=await response.json();if(response.status===401){configUnlocked=false;openConfigAuth(document.querySelector('.nav[data-view="config"]'));return}if(!response.ok)throw new Error(body.detail||'更新启动失败');await waitForUpdatedService()}catch(error){message.textContent=`更新失败：${error.message}`}finally{button.disabled=false;button.textContent='更新代码并重启'}};
$('#configAuthForm').onsubmit=async e=>{e.preventDefault();const message=$('#configAuthMessage'),password=$('#configPassword').value,purpose=pendingProtectedPurpose;message.textContent='验证中…';try{const response=await fetch('/api/config/auth',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})}),body=await response.json();if(!response.ok)throw new Error(body.detail||'口令错误');configUnlocked=true;const button=pendingConfigButton,syncUrl=pendingConfigUrlSync;closeConfigAuth();if(button){if(purpose==='license'){licenseUnlocked=true;await loadLicenses()}activateView(button,{syncUrl});if(purpose==='config')await loadConfig()}}catch(error){message.textContent=error.message||'口令错误';$('#configPassword').select()}};
$('#configAuthCancel').onclick=()=>{const returnToOverview=['config','licenses'].includes(viewForLocation());closeConfigAuth();if(returnToOverview){const overview=document.querySelector('.nav[data-view="overview"]');activateView(overview,{syncUrl:true,replace:true})}};

// LSF 10.1 does not provide reliable per-job CPU or memory usage values.
// Keep the job and user views focused on fields that are actually observed;
// the assignments intentionally replace the legacy renderers above so older
// cached bundles cannot add misleading 0% columns back to the page.
renderSummary=function(s){const t=s.totals||{},e=s.efficiency||{},memoryTotal=Number(t.total_mem_mb)||0,memoryFree=memoryTotal?Math.min(memoryTotal,Math.max(0,Number(t.free_mem_mb)||0)):Math.max(0,Number(t.free_mem_mb)||0),memoryFreePct=memoryTotal?Math.round(memoryFree/memoryTotal*100):null,memoryUsedPct=memoryTotal?Math.max(0,100-memoryFreePct):null;const data=[['运行作业',t.running_jobs,'RUN'],['等待作业',t.pending_jobs,'PEND'],['异常退出',t.exit_jobs,'EXIT'],['运行Slots',`${t.running_slots}/${t.max_slots}`,'SLOT'],['License风险',t.license_risks,'RISK']];$('#kpis').innerHTML=data.map(x=>`<div class="kpi"><small>${x[0]}</small><strong>${x[1]}</strong><em>${x[2]}</em></div>`).join('');const gauges=[{label:'CPU 利用率',display:`${e.cpu_pct??0}%`,value:e.cpu_pct??0},{label:memoryTotal?'内存利用率':'可用内存',display:memoryTotal?`${memoryUsedPct}%`:capacity(memoryFree),value:memoryUsedPct??0,detail:memoryTotal?`已用 ${capacity(memoryTotal-memoryFree)} / 总 ${capacity(memoryTotal)} · 可用 ${capacity(memoryFree)}`:'LSF 未提供 lshosts 总内存'},{label:'Slot 利用率',display:`${e.slot_pct??0}%`,value:e.slot_pct??0}];$('#gauges').innerHTML=gauges.map((g,i)=>`<div class="gauge"><div class="ring" style="--value:${g.value??0};--color:${['var(--cyan)','var(--blue)','var(--yellow)'][i]}"><strong>${g.display}</strong></div><p>${g.label}${g.detail?`<small class="gauge-detail">${g.detail}</small>`:''}</p></div>`).join('')};
  renderJobs=function(rows){if(rows){allJobs=rows;jobPage=1}const query=$('#jobSearch').value.trim().toLowerCase(),status=$('#jobStatus').value,queue=$('#jobQueue').value.trim().toLowerCase(),node=$('#jobNode').value.trim().toLowerCase(),sort=$('#jobSort').value,esc=value=>String(value??'-').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));const visible=allJobs.filter(j=>{const text=`${j.job_name||''} ${j.user||''} ${j.project||''}`.toLowerCase(),nodes=`${j.submit_host||''} ${j.exec_host||''}`.toLowerCase(),jobStatus=String(j.status||'').toUpperCase(),statusMatch=status==='PEND'?['PEND','PSUSP'].includes(jobStatus):!status||jobStatus===status;return (!query||text.includes(query))&&statusMatch&&(!queue||String(j.queue||'').toLowerCase().includes(queue))&&(!node||nodes.includes(node))}).sort((a,b)=>{if(sort==='job_id')return (Number(b.job_id)||0)-(Number(a.job_id)||0);if(sort==='slots')return (Number(b.slots)||0)-(Number(a.slots)||0);return String(b.submit_time||'').localeCompare(String(a.submit_time||''))});jobPage=renderPager('#jobPagination',jobPage,visible.length,page=>{jobPage=page;renderJobs()});const pageRows=visible.slice((jobPage-1)*PAGE_SIZE,jobPage*PAGE_SIZE);$('#jobResultCount').textContent=`${visible.length} / ${allJobs.length} 个作业`;$('#jobRows').innerHTML=pageRows.length?pageRows.map(j=>{const jobStatus=String(j.status||'-').toUpperCase(),pending=jobStatus==='PEND'||jobStatus==='PSUSP',reason=pending&&j.pending_reason?`<small class="job-pending-reason" title="${esc(j.pending_reason)}">${esc(j.pending_reason)}</small>`:'',retained=j.retained_terminal?'<small class="job-retained-tag">7 天保留记录</small>':'';return `<tr><td><button type="button" class="job-id-link" data-job-detail="${esc(j.job_id)}">${esc(j.job_id)}</button>${retained}</td><td><span class="job-name" title="${esc(j.job_name)}">${esc(j.job_name)}</span></td><td>${esc(j.user)}</td><td>${esc(j.project)}</td><td><div class="job-status-cell"><span class="status ${esc(jobStatus)}">${esc(jobStatus)}</span>${reason}</div></td><td>${esc(j.queue)}</td><td>${esc(j.submit_host)}</td><td>${esc(j.exec_host)}</td><td>${esc(j.submit_time?j.submit_time.replace('T',' ').slice(0,16):'-')}</td><td>${esc(j.slots)}</td></tr>`}).join(''):'<tr><td colspan="10" class="empty-state">没有匹配的作业。</td></tr>'};
renderUsers=function(rows){if(rows){allUsers=rows;userPage=1}const query=$('#userSearch').value.trim().toLowerCase(),activity=$('#userActivityFilter').value,sort=$('#userSort').value;const visible=allUsers.filter(u=>{const name=String(u.user||'').toLowerCase(),running=Number(u.running_jobs)||0,pending=Number(u.pending_jobs)||0,exit=Number(u.exit_jobs)||0;return (!query||name.includes(query))&&(!activity||(activity==='running'&&running>0)||(activity==='pending'&&pending>0)||(activity==='exit'&&exit>0)||(activity==='idle'&&!running&&!pending&&!exit))}).sort((a,b)=>{if(sort==='user')return String(a.user||'').localeCompare(String(b.user||''));return (Number(b[sort])||0)-(Number(a[sort])||0)});userPage=renderPager('#userPagination',userPage,visible.length,page=>{userPage=page;renderUsers()});const pageRows=visible.slice((userPage-1)*PAGE_SIZE,userPage*PAGE_SIZE);$('#userResultCount').textContent=`${visible.length} / ${allUsers.length} 位用户`;$('#userRows').innerHTML=pageRows.length?pageRows.map(u=>`<tr><td><strong>${u.user}</strong><small class="user-job-count">${u.total_jobs} 个作业</small></td><td><span class="status RUN">${u.running_jobs} RUN</span></td><td><span class="status PEND">${u.pending_jobs} PEND</span></td><td>${u.exit_jobs?`<span class="status EXIT">${u.exit_jobs} EXIT</span>`:'—'}</td><td><strong>${u.running_slots}</strong></td><td>${u.total_slots}</td></tr>`).join(''):'<tr><td colspan="6" class="empty-state">没有符合条件的用户。</td></tr>'};
renderQueues=function(rows){if(rows)allQueues=rows;const query=$('#queueSearch').value.trim().toLowerCase(),statusFilter=$('#queueStatusFilter').value,loadFilter=$('#queueLoadFilter').value,sort=$('#queueSort').value,statusKey=status=>{const value=String(status||'').toLowerCase();return value.includes('inact')?'inactive':value.includes('open')?'open':value.includes('closed')?'closed':'other'},statusLabel=status=>{const key=statusKey(status),value=String(status||'').toLowerCase();return key==='open'?(value.includes('active')?'开放·活跃':'开放'):key==='inactive'?'窗口未开启':key==='closed'?'已关闭':status||'未知'},esc=value=>String(value??'-').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));const numberOf=key=>allQueues.reduce((sum,q)=>sum+(Number(q[key])||0),0),summaryTotals=latestSummary?.totals||{},totalRunning=Number.isFinite(Number(summaryTotals.running_jobs))?Number(summaryTotals.running_jobs):numberOf('running'),totalPending=Number.isFinite(Number(summaryTotals.pending_jobs))?Number(summaryTotals.pending_jobs):numberOf('pending'),totalSuspended=numberOf('suspended'),boundedQueues=allQueues.filter(q=>(Number(q.max_slots)||0)>0),totalMax=boundedQueues.reduce((sum,q)=>sum+(Number(q.max_slots)||0),0),overallUtil=totalMax?pct(totalRunning,totalMax):null;$('#queueSummary').innerHTML=[['队列总数',allQueues.length,'已采集队列'],['开放队列',allQueues.filter(q=>statusKey(q.status)==='open').length,'可接收作业'],['运行作业',totalRunning,'作业快照 RUN'],['等待作业',totalPending,totalPending?'作业快照存在排队':'作业快照当前无排队'],['挂起作业',totalSuspended,'队列 SUSP'],['并发利用率',overallUtil===null?'—':`${overallUtil}%`,totalMax?`${totalRunning} / ${totalMax} 个上限`:'队列未设置统一上限']].map((item,index)=>`<div class="queue-summary-card ${index===3&&totalPending?'warn':''}"><small>${item[0]}</small><strong>${item[1]}</strong><span>${item[2]}</span></div>`).join('');const visible=allQueues.filter(q=>{const name=String(q.name||'').toLowerCase(),running=Number(q.running)||0,pending=Number(q.pending)||0,suspended=Number(q.suspended)||0;return (!query||name.includes(query))&&(!statusFilter||statusKey(q.status)===statusFilter)&&(!loadFilter||(loadFilter==='running'&&running>0)||(loadFilter==='pending'&&pending>0)||(loadFilter==='suspended'&&suspended>0)||(loadFilter==='idle'&&!running&&!pending&&!suspended))}).sort((a,b)=>{if(sort==='name')return String(a.name||'').localeCompare(String(b.name||''));if(sort==='utilization'){const av=Number(a.max_slots)>0?Number(a.running)/Number(a.max_slots):-1,bv=Number(b.max_slots)>0?Number(b.running)/Number(b.max_slots):-1;return bv-av}return (Number(b[sort])||0)-(Number(a[sort])||0)});$('#queueResultCount').textContent=`${visible.length} / ${allQueues.length} 个队列`;$('#queueRows').innerHTML=visible.length?visible.map(q=>{const running=Number(q.running)||0,pending=Number(q.pending)||0,suspended=Number(q.suspended)||0,max=Number(q.max_slots)||0,perUser=Number(q.per_user_slots)||0,util=max?pct(running,max):null,statusClass=statusKey(q.status),loadClass=pending?'queue-load-warning':running?'queue-load-active':'queue-load-idle',loadText=pending?`等待 ${pending} 个作业`:running?`运行中 ${running} 个作业`:'当前空闲',hostNames=(()=>{try{const parsed=JSON.parse(q.host_names||'[]');return Array.isArray(parsed)?parsed.map(value=>String(value)).filter(Boolean):[]}catch(error){return []}})(),hostText=hostNames.length?hostNames.join(', '):'未提供队列节点信息';return `<tr><td><div class="queue-name-cell queue-host-tooltip" tabindex="0" data-tooltip="包含节点：${esc(hostText)}"><strong>${esc(q.name)}</strong><small>${max?`MAX ${max} 个并发作业`:'MAX 未限制'}</small></div></td><td><span class="queue-status ${statusClass}">${esc(statusLabel(q.status))}</span></td><td><div class="queue-main-number"><strong>${running}</strong><span>/ ${max||'不限'}</span></div></td><td><div class="queue-user-limit"><strong>${perUser||'不限'}</strong><small>${perUser?'每用户 Slots':'未设置 JL/U'}</small></div></td><td><span class="queue-count pending">${pending}</span></td><td><span class="queue-count suspended">${suspended}</span></td><td><div class="queue-utilization"><strong>${util===null?'—':`${util}%`}</strong>${util===null?'<small>未设置上限</small>':`<div class="bar"><i style="width:${Math.min(100,util)}%"></i></div>`}</div></td><td><span class="queue-load ${loadClass}">${loadText}</span></td></tr>`}).join(''):'<tr><td colspan="8" class="empty-state">没有符合条件的队列。</td></tr>'};

async function openJobDetail(jobId){const modal=$('#jobDetailModal'),title=$('#jobDetailTitle'),status=$('#jobDetailStatus'),content=$('#jobDetailContent');title.textContent=`Job ${jobId} 详情`;status.textContent='正在读取 bjobs -l…';content.textContent='';modal.hidden=false;try{const result=await api(`/api/jobs/${encodeURIComponent(jobId)}/detail`,{timeout:30000});status.textContent=result.source==='retained'?'EXIT 时保存的 bjobs -l 详情（保留 7 天）':'来自 LSF 实时查询（bjobs -l）';content.textContent=result.detail||'LSF 未返回详情';}catch(error){status.textContent='读取失败';content.textContent=error.message||'无法读取作业详情';}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-job-detail]');if(button)openJobDetail(button.dataset.jobDetail);});
$('#jobDetailClose').onclick=()=>{$('#jobDetailModal').hidden=true;};
